function vxAdd(k,pre,o){const r=Object.assign({ID:vxNext(k,pre)},o);if(VXS[k][1].includes("Usuario")&&!r.Usuario)r.Usuario=vxUser();if(VXS[k][1].includes("Registrado")&&!r.Registrado)r.Registrado=nowTs();VX.book[k].push(r);vxLog("CREA",k,r.ID,"");vxChanged();return r;}
function vxUpd(k,r,ch){const det=[];for(const f in ch){const a=r[f],b=ch[f];const sa=a instanceof Date?iso(a):(a==null?"":String(a)),sb=b instanceof Date?iso(b):(b==null?"":String(b));if(sa!==sb){det.push(f+": "+sa+" → "+sb);r[f]=b;}}if(det.length){vxLog("MODIFICA",k,r.ID||r.Paciente,det.join("; "));vxChanged();}return det.length;}
