 const vi=vxVacEstado(p,c).filter(e=>e.cls==="warn").map(e=>e.v.l);if(vi.length)A("Vacunación incompleta: "+vi.slice(0,4).join(", ")+(vi.length>4?" y "+(vi.length-4)+" más":""),"dato");
