const vxPrfIn=(id,re,a,b)=>vxL(id,"prf").some(x=>re.test(x.Medicamento)&&vxD(x.Inicio)&&vxD(x.Inicio)<=b&&(!vxD(x.Fin)||vxD(x.Fin)>=a));
