function vxCount(L,f){const g={};L.forEach(p=>{const k=f(p)||"Sin dato";g[k]=(g[k]||0)+1;});return Object.entries(g).sort((a,b)=>b[1]-a[1]);}
function vxPiramide(L,c){const G=["Menor de 15","15 a 19","20 a 29","30 a 39","40 a 49","50 a 59","60 y más"];const m={},f={};L.forEach(p=>{const g=vxGrupoEtario(vxEdad(p,c));if(String(p.Sexo).startsWith("F"))f[g]=(f[g]||0)+1;else m[g]=(m[g]||0)+1;});const mx=Math.max(1,...G.map(g=>Math.max(m[g]||0,f[g]||0)));
 const W=520,rh=24,top=22,H=top+G.length*rh+6,cx=W/2,lw=70,sc=(cx-lw/2-30)/mx;
 return'<svg class="chart" viewBox="0 0 '+W+' '+H+'" role="img" aria-label="Pirámide de edad por sexo"><text x="'+(cx-lw/2-6)+'" y="14" text-anchor="end" class="ax">Masculino</text><text x="'+(cx+lw/2+6)+'" y="14" class="ax">Femenino</text>'+G.map((g,i)=>{const y=top+i*rh;const a=(m[g]||0)*sc,b=(f[g]||0)*sc;return'<rect x="'+(cx-lw/2-a)+'" y="'+y+'" width="'+a+'" height="'+(rh-6)+'" rx="3" fill="var(--accent)"/><rect x="'+(cx+lw/2)+'" y="'+y+'" width="'+b+'" height="'+(rh-6)+'" rx="3" fill="#7a9fb0"/><text x="'+cx+'" y="'+(y+13)+'" text-anchor="middle" class="ax">'+g+'</text>'+(m[g]?'<text x="'+(cx-lw/2-a-4)+'" y="'+(y+13)+'" text-anchor="end" class="val">'+m[g]+'</text>':'')+(f[g]?'<text x="'+(cx+lw/2+b+4)+'" y="'+(y+13)+'" class="val">'+f[g]+'</text>':'');}).join("")+'</svg>';}
