/* solicitud del mes: la genera Laboratorio; el programa la ve y la corrige con motivo */
function vxSolView(ctx){const mes=vxLabMes();const R=vxSolRecs(mes).filter(r=>vxP(r.Paciente)&&(ctx==="lab"||vxFiltro(vxP(r.Paciente))));const gen=R.length>0;
 let h='<div class="panel" style="display:grid;gap:10px"><div class="mhead"><div><h3 style="margin:0">Solicitud de laboratorio · VIH · '+esc(mes)+'</h3><p class="note" style="margin:3px 0 0">Calculada con las frecuencias del contrato de cada EPS (guías rápidas adjuntas), los resultados vencidos y las condiciones clínicas (CD4, atazanavir, prueba reactiva).</p></div><div class="copyrow"><label class="f" style="max-width:160px">Mes<input type="month" id="vxlmes" value="'+esc(mes)+'"></label>'+(ctx==="lab"?'<button type="button" class="btn primary" data-x="solgen">'+(gen?"Agregar faltantes":"Generar solicitud")+'</button>':'')+'<button type="button" class="btn" data-x="soladd">Agregar examen</button><button type="button" class="btn" data-x="rep|sol">Descargar</button></div></div>';
 if(!gen){const prev=vxPacs().filter(p=>vxSt(p,monthEnd(pdate(mes+"-01"))).activo).reduce((a,p)=>a+vxDue(p,mes).length,0);return h+'<p class="note">Sin solicitud generada para '+esc(mes)+'. Previsto: '+prev+' exámenes. '+(ctx==="lab"?"":"La genera y valida Laboratorio clínico; aquí se ve y se corrige.")+'</p></div>';}
 const by={};R.forEach(r=>{(by[r.Paciente]=by[r.Paciente]||[]).push(r);});const tom=R.filter(r=>r.Estado==="Muestra tomada").length,res=R.filter(vxSolTieneRes).length;
 h+=vxTiles([[R.length,"exámenes solicitados"],[Object.keys(by).length,"pacientes"],[tom,"muestras tomadas"],[res,"con resultado cargado",res===R.length?"ok":""]]);
 h+='<div class="tablebox"><table><thead><tr><th>Paciente</th><th>Exámenes</th><th>Estado</th><th></th></tr></thead><tbody>'+Object.entries(by).map(([pid,L])=>{const p=vxP(pid);return'<tr><td>'+vxPacCell(p)+'<span class="sub">'+esc(p.EPS)+'</span></td><td style="font-size:13px">'+L.map(r=>'<span class="ch'+(vxSolTieneRes(r)?'':r.Estado==="No tomada"?' bad':'')+'" title="'+esc(r.Origen)+'">'+esc(r.Examen)+(vxSolTieneRes(r)?' ✓':'')+'</span> <button type="button" class="lnk" style="font-size:11px" data-x="solquitar|'+r.ID+'" title="Quitar con motivo">×</button>').join(" ")+'</td><td>'+[...new Set(L.map(r=>r.Estado))].map(esc).join(", ")+'</td><td>'+(ctx==="lab"?'<button type="button" class="btn sm" data-x="soltom|'+pid+'|'+mes+'">Muestra tomada</button> ':'')+'<button type="button" class="btn sm" data-x="labnew|'+pid+'">Cargar resultado</button></td></tr>';}).join("")+'</tbody></table></div></div>';return h;}

/* ---------- TAR ---------- */
function vxTarV(){const sub=VX.ui.tsub||"gru";const c=vxCorte();const P=vxPacs().filter(p=>vxFiltro(p)&&vxSt(p,c).activo);const S=P.map(p=>vxSt(p,c));
 let h='<div class="mhead" style="margin-top:6px"><div class="seg">'+[["gru","Grupos farmacológicos"],["esq","Esquemas por paciente"],["ent","Entregas"],["ped","Pedido de fin de mes"]].map(([k,l])=>'<button type="button" data-x="tsub|'+k+'" aria-pressed="'+(sub===k)+'">'+l+'</button>').join("")+'</div><div class="copyrow"><button type="button" class="btn" data-x="rep|tar">TAR por paciente</button><button type="button" class="btn" data-x="rep|ped">Pedido del mes</button></div></div>';
 if(sub==="gru"){const T=S.filter(s=>s.tar);const med={};T.forEach(s=>(VXQ[s.tar.Esquema]?VXQ[s.tar.Esquema].c:[]).forEach(m=>med[m]=(med[m]||0)+1));
  h+=vxTiles([[T.length,"pacientes en TAR"],[vxPctTxt(T.filter(s=>VXQ[s.tar.Esquema]&&VXQ[s.tar.Esquema].c.includes("DTG")).length,T.length),"con dolutegravir"],[vxPctTxt(T.filter(s=>VXQ[s.tar.Esquema]&&VXQ[s.tar.Esquema].c.some(m=>VX_MED[m][1]==="IP")).length,T.length),"con inhibidor de proteasa"],[vxPctTxt(T.filter(s=>VXQ[s.tar.Esquema]&&VXQ[s.tar.Esquema].c.some(m=>VX_MED[m][1]==="ITINN")).length,T.length),"con ITINN"],[vxPctTxt(T.filter(s=>VX_GPC_PREF.includes(s.tar.Esquema)).length,T.length),"en pauta de elección GPC 2021"]]);
  h+='<div class="pxcols"><div class="panel"><h3>Grupos farmacológicos</h3>'+vxClasesChart(S)+'</div><div class="panel"><h3>Medicamento (pacientes que lo reciben)</h3>'+hbars(Object.entries(med).sort((a,b)=>b[1]-a[1]).map(([m,n])=>[VX_MED[m][0]+" · "+VX_MED[m][1],n]))+'</div><div class="panel"><h3>Esquema</h3>'+hbars(vxCount(T,s=>s.tar.Esquema))+'</div><div class="panel"><h3>Línea de tratamiento</h3>'+hbars(vxCount(T,s=>s.tar.Linea||"Sin dato"))+'</div></div>';
  h+='<p class="note">Grupos: INI inhibidores de integrasa; ITIAN y ITINN inhibidores de transcriptasa reversa nucleósidos y no nucleósidos; IP inhibidores de proteasa. Pauta de elección: GPC VIH adultos Colombia 2021, recomendaciones 12 y 13. TDF/3TC/DTG no cuenta como pauta de elección (la GPC lista DTG + TDF/FTC; no se consideran equivalentes).</p>';return h;}
 if(sub==="esq")return h+'<div class="panel tablebox" style="padding:0"><table><thead><tr><th>Paciente</th><th>Esquema actual</th><th>Desde</th><th>Inicio de TAR</th><th class="num">Semanas</th><th>Última entrega</th><th>Cubre hasta</th></tr></thead><tbody>'+S.map(s=>'<tr class="click" data-x="pac|'+s.id+'"><td>'+vxPacCell(s.p)+'</td><td>'+(s.tar?esc(s.tar.Esquema):'<span class="bad-t">Sin TAR</span>')+'</td><td class="mono">'+(s.tar?esc(s.tar.Inicio):"")+'</td><td class="mono">'+(s.tarIni?iso(s.tarIni):"")+'</td><td class="num">'+(s.semTAR==null?"":s.semTAR)+'</td><td class="mono">'+(s.ent?esc(s.ent.Fecha):"—")+'</td><td class="mono'+(s.cob&&s.cob<TODAY()?' bad-t':'')+'">'+(s.cob?iso(s.cob):"—")+'</td></tr>').join("")+'</tbody></table></div>';
 if(sub==="ent"){const m=VX.ui.emes||ym(TODAY());const E=VX.book.ent.filter(vxLive).filter(e=>String(e.Fecha).startsWith(m)&&vxP(e.Paciente)&&vxFiltro(vxP(e.Paciente)));
  return h+'<div class="copyrow"><label class="f" style="max-width:160px">Mes<input type="month" id="vxemes" value="'+esc(m)+'"></label><button type="button" class="btn primary" data-x="entnew">Registrar entrega</button></div><div class="panel tablebox" style="padding:0"><table><thead><tr><th>Fecha</th><th>Paciente</th><th>Esquema</th><th class="num">Meses</th><th class="num">Unidades</th><th>Lugar</th></tr></thead><tbody>'+(E.map(e=>'<tr><td class="mono">'+esc(e.Fecha)+'</td><td>'+vxPacCell(vxP(e.Paciente))+'</td><td>'+esc(e.Esquema)+'</td><td class="num">'+esc(e.Meses)+'</td><td class="num">'+esc(e.Unidades)+'</td><td>'+esc(e.Lugar||"")+'</td></tr>').join("")||'<tr><td colspan="6" class="note">Sin entregas en el mes.</td></tr>')+'</tbody></table></div>';}
 if(sub==="ped"){const PD=vxPedido();h+='<p class="note">Mes del pedido: <b>'+esc(PD.mes)+'</b>. Entra cada paciente activo en TAR cuya cobertura vence antes de terminar ese mes; la cantidad es tabletas por día × 30 × meses de dispensación de su última entrega. Las cantidades van en <b>unidades</b> (tabletas o cápsulas), sin convertir a cajas.</p>';
  h+='<div class="pxcols"><div class="panel tablebox" style="padding:0"><table><thead><tr><th>Producto</th><th class="num">Pacientes</th><th class="num">Unidades</th></tr></thead><tbody>'+PD.cons.map(r=>'<tr><td>'+esc(r.prod)+'</td><td class="num">'+r.pac+'</td><td class="num mono">'+r.u.toLocaleString("es-CO")+'</td></tr>').join("")+'</tbody></table></div><div class="panel tablebox" style="padding:0"><table><thead><tr><th>Paciente</th><th>Esquema</th><th>Cubre hasta</th><th class="num">Meses</th></tr></thead><tbody>'+PD.rows.map(r=>'<tr><td>'+vxPacCell(r.p)+'</td><td>'+esc(r.esq)+'</td><td class="mono">'+iso(r.cob)+'</td><td class="num">'+r.meses+'</td></tr>').join("")+'</tbody></table></div></div>';return h;}
 return h;}
function vxPedido(mes){mes=mes||ym(addMonths(TODAY(),1));const me=monthEnd(pdate(mes+"-01"));const c=vxCorte();const rows=[];const cons={};
 vxPacs().filter(p=>vxFiltro(p)).forEach(p=>{const s=vxSt(p,TODAY()>c?TODAY():c);if(!s.activo||!s.tar)return;const q=VXQ[s.tar.Esquema];if(!q||!q.it.length)return;if(s.cob&&s.cob>me)return;const meses=num(s.ent&&s.ent.Meses)||1;rows.push({p,esq:s.tar.Esquema,cob:s.cob,meses});q.it.forEach(([prod,tpd])=>{const r=cons[prod]=cons[prod]||{prod,pac:0,u:0};r.pac++;r.u+=tpd*30*meses;});});
 return{mes,rows,cons:Object.values(cons).sort((a,b)=>b.u-a.u)};}

