function vxDlgPrcOrd(pid,tipo){openDlg("Ordenar procedimiento · "+pid,'<div class="form">'+vxFld("po_t","Procedimiento","sel",tipo||"",VX_PRC)+vxFld("po_f","Fecha de la orden","date",pxToday())+'</div><p class="note">Queda en la lista de enfermería; cuando enfermería confirme la aplicación o la toma, se carga en la historia clínica.</p>',"Ordenar",()=>{if(!vxGv("po_t"))return"Elija el procedimiento.";vxAdd("prc","PR-",{Paciente:pid,Tipo:vxGv("po_t"),Ordenado:vxGv("po_f"),OrdenadoPor:vxUser(),Fecha:"",Lote:"",FechaLectura:"",Lectura:"",Resultado:"",Estado:"Ordenado"});pxRender();toast("Procedimiento ordenado.");});}
