 if(x.Estado==="Ordenado")return openDlg("Confirmar "+(ppd?"aplicación":"toma")+" · "+x.Tipo,'<p class="note">'+esc(p.ID+" · "+vxNom(p))+'</p><div class="form">'+vxFld("pc_f","Fecha de "+(ppd?"aplicación":"toma"),"date",pxToday())+vxFld("pc_l",ppd?"Lote del PPD":"Observación","text","")+'</div>'+(ppd?'<p class="note">Programe la lectura entre 48 y 72 horas: '+iso(addDays(TODAY(),2))+' a '+iso(addDays(TODAY(),3))+'.</p>':''),"Confirmar",()=>{if(!vxGv("pc_f"))return"Escriba la fecha.";vxUpd("prc",x,{Fecha:vxGv("pc_f"),Lote:vxGv("pc_l"),Estado:ppd?"Aplicado":"Tomada"});pxRender();toast("Confirmado y cargado en la historia clínica.");});
