function vxIsBook(wb){return wb.SheetNames.includes("Pacientes")&&wb.SheetNames.includes("EsquemasTAR");}
function vxParse(wb){const b=vxNewBook();VXK.forEach(k=>{const ws=wb.Sheets[VXS[k][0]];if(!ws)return;b[k]=XLSX.utils.sheet_to_json(ws,{defval:"",raw:false}).map(r=>{const o={};VXS[k][1].forEach(c=>{let v=r[c];o[c]=v==null?"":String(v);});return o;});});return b;}
function vxBuildWb(){const wb=XLSX.utils.book_new();VXK.forEach(k=>{const[n,cols]=VXS[k];const aoa=[cols].concat(VX.book[k].map(r=>cols.map(c=>r[c]==null?"":r[c])));XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(aoa),n);});return wb;}
async function vxExportBook(){if(!VX.book)return;const ok=await saveWb(vxBuildWb(),"Libro_programa_VIH_"+pxToday()+".xlsx");if(ok){VX.dirty=false;pxRender();}}
function vxOpenBook(b,demo){VX.book=b;VX.demo=!!demo;VX.dirty=false;vxChanged();VX.dirty=false;if(!vxCfg("contrato",null))VX.book.cfg.push({Clave:"contrato",Valor:JSON.stringify(VX_CONTRATO_DEF)});}
function vxReadFile(f){return new Promise((ok,ko)=>{const rd=new FileReader();rd.onload=ev=>{try{ok(XLSX.read(new Uint8Array(ev.target.result),{type:"array",cellDates:true}));}catch(e){ko(e);}};rd.onerror=ko;rd.readAsArrayBuffer(f);});}
async function vxOnBook(f){try{const wb=await vxReadFile(f);if(!vxIsBook(wb)){toast("Ese archivo no es un libro del programa VIH. Para la cohorte nominal o el archivo CAC use «Importar».");return;}vxOpenBook(vxParse(wb),false);pxRender();toast("Libro VIH cargado: "+vxPacs().length+" pacientes.");}catch(e){console.error(e);toast("No se pudo leer el archivo: "+e.message);}}

