async function vxCompare(f){try{const wb=await vxReadFile(f);let rows=null;for(const sn of wb.SheetNames){const A=XLSX.utils.sheet_to_json(wb.Sheets[sn],{header:1,raw:true,defval:null});const hi=A.findIndex(r=>r&&r.some(c=>vxNH(c)==="CONSECUTIVO"));if(hi<0)continue;const H=A[hi].map(vxNH);rows=A.slice(hi+1).filter(r=>r&&r[H.findIndex(h=>/NUMERO DE IDENTIFICACION/.test(h))]).map(r=>Object.fromEntries(H.map((h,i)=>[h,r[i]])));break;}
 if(!rows){toast("No se encontró la plantilla de la cohorte nominal en ese archivo.");return;}const mine=vxNominalRows("NUEVA EPS");const M=new Map(mine.map(x=>[String(x.p.Documento),x]));const B=new Map(rows.map(r=>[String(r["NUMERO DE IDENTIFICACION"]).replace(/\D/g,""),r]));
 const onlyB=[...B.keys()].filter(k=>!M.has(k)).length,onlyM=[...M.keys()].filter(k=>!B.has(k)).length;const both=[...B.keys()].filter(k=>M.has(k));const un=new Set([...B.keys(),...M.keys()]).size;
 const cmp=(n,f)=>{const d=both.filter(k=>f(B.get(k))!==f(M.get(k).r)).length;return{n,pct:both.length?d/both.length*100:0,det:d+" de "+both.length+" pacientes en ambas bases"};};
 VX.ui.cmp=[{n:"Pacientes presentes en una sola base",pct:un?(onlyB+onlyM)/un*100:0,det:onlyB+" solo en la enviada · "+onlyM+" solo en el libro"},cmp("Recibe TAR",r=>String(r["RECIBE TRATAMIENTO ANTIRETROVIRAL ACTUALMENTE"]||"").trim().toUpperCase()),cmp("Resultado de la última carga viral",r=>String(r["RESULTADO ULTIMA CARGA VIRAL"]||"").trim().charAt(0)),cmp("Fecha del último CD4",r=>vxDt(r["FECHA ULTIMO CD4"]||r["FECHA  ULTIMO CD4"]))];pxRender();toast("Comparación lista.");}catch(e){console.error(e);toast("No se pudo comparar: "+e.message);}}
