/* ================= v0.5 · PROGRAMA VIH · valoraciones por disciplina, HC, nota de enfermería, auditoría CAC y validación de TAR ================= */
/* SMAQ (Knobel H et al. AIDS 2002;16:605-13): no adherente si olvida, no toma a la hora, deja de tomar si se siente mal, olvidó el fin de semana,
   omitió más de 2 dosis en la última semana o más de 2 días completos desde la última visita. */
const VX_SMAQ=[["q1","¿Alguna vez olvida tomar la medicación?",["Sí","No"]],["q2","¿Toma siempre los fármacos a la hora indicada?",["Sí","No"]],["q3","¿Alguna vez deja de tomar los fármacos si se siente mal?",["Sí","No"]],["q4","¿Olvidó tomar la medicación durante el fin de semana?",["Sí","No"]],["q5","En la última semana, ¿cuántas veces no tomó alguna dosis?",["Ninguna","1 a 2","3 a 5","6 a 10","Más de 10"]],["q6","Desde la última visita, ¿cuántos días completos no tomó la medicación?",null]];
function vxSmaqRes(d){if(!d||!d.q1)return"";const no=d.q1==="Sí"||d.q2==="No"||d.q3==="Sí"||d.q4==="Sí"||["3 a 5","6 a 10","Más de 10"].includes(d.q5)||num(d.q6)>2;return no?"No adherente":"Adherente";}
function vxSmaqTxt(j){let d={};try{d=typeof j==="string"?JSON.parse(j||"{}"):j;}catch(e){}if(!d.q1)return"";return"olvida: "+d.q1.toLowerCase()+"; toma a la hora: "+String(d.q2).toLowerCase()+"; suspende si se siente mal: "+String(d.q3).toLowerCase()+"; olvidó el fin de semana: "+String(d.q4).toLowerCase()+"; dosis omitidas en la semana: "+String(d.q5).toLowerCase()+"; días completos sin tomar: "+(d.q6||"0");}
/* validación de seguridad de la TAR */
const VX_TARCHK=[["c1","Conciliación medicamentosa (TAR previo y medicamentos no TAR)"],["c2","Interacciones farmacológicas revisadas"],["c3","Función renal revisada (TFG) si el esquema tiene tenofovir"],["c4","Estado de hepatitis B revisado (HBsAg) antes de iniciar o suspender tenofovir o lamivudina"],["c5","HLA-B*5701 negativo si el esquema tiene abacavir"],["c6","Gestación o deseo reproductivo considerado"],["c7","Genotipo revisado si el cambio es por falla virológica"],["c8","Educación al paciente sobre dosis, horario y efectos adversos"]];
function vxTarChkApl(p,esq,motivo){const s=vxSt(p,TODAY());const q=VXQ[esq]||{c:[]};return{c3:q.c.some(m=>m==="TDF"),c4:q.c.some(m=>["TDF","TAF","3TC","FTC"].includes(m))||!!(s.tar&&VXQ[s.tar.Esquema]&&VXQ[s.tar.Esquema].c.some(m=>["TDF","TAF","3TC","FTC"].includes(m))),c5:q.c.includes("ABC"),c6:String(p.Sexo).startsWith("F"),c7:motivo==="Falla virológica"};}
function vxDlgTar(pid,modo){const p=vxP(pid);const s=vxSt(p,TODAY());const val=modo==="validar";const t=val?s.tar:null;if(val&&!t){toast("El paciente no tiene esquema activo.");return;}
 const cr=vxLast(pid,"Cr");const tfg=cr?vxTFG(vxVal(cr),vxEdad(p,cr._d),p.Sexo):null;const hb=vxLast(pid,"HBsAg");const hla=vxLast(pid,"HLAB5701");let prev={};try{prev=JSON.parse((t&&t.Validacion)||"{}");}catch(e){}
 openDlg(val?"Validar esquema "+t.Esquema+" · "+pid:(s.tar?"Cambiar":"Iniciar")+" esquema TAR · "+pid,'<p class="note">Seguridad del paciente: el esquema queda activo solo con TAR previo documentado y la lista de validación completa.</p><div class="form">'+vxFld("ta_pv","TAR previo al ingreso","sel",p.TARPrevio||"",["Naive (sin TAR previo)","Experimentado (TAR previo)","Sin dato verificable"])+vxFld("ta_pd","Esquemas previos (fechas, motivo de cambio, fuente)","area",p.TARPrevioDetalle||"",2,"wide")+
 (val?'':vxFld("ta_e","Esquema","sel","",VX_ESQ.filter(e=>e.it.length).map(e=>e.n))+vxFld("ta_i","Fecha de inicio (primera dosis)","date",pxToday())+vxFld("ta_l","Línea","sel",s.tar?"Segunda línea":"Primera línea",["Primera línea","Segunda línea","Tercera línea o rescate","Simplificación"])+vxFld("ta_m","Motivo","sel",s.tar?"":"Inicio",["Inicio","Simplificación","Toxicidad o evento adverso","Falla virológica","Interacción farmacológica","Gestación","Desabastecimiento","Comorbilidad","Otro"]))+'</div>'+
 '<p class="note">Datos para validar: TFG '+(tfg?vxF(tfg,0)+" mL/min ("+iso(cr._d)+")":"sin creatinina")+' · HBsAg '+(hb?esc(hb.Resultado)+" ("+iso(hb._d)+")":"sin dato")+' · HLA-B*5701 '+(hla?esc(hla.Resultado):"sin dato")+' · Gestante '+esc(p.Gestante||"NO")+'.</p><fieldset class="pxfs"><legend>Validación de seguridad</legend>'+VX_TARCHK.map(([k,l])=>'<label class="chk"><input type="checkbox" data-tchk="'+k+'"'+(prev[k]?" checked":"")+'> '+esc(l)+'</label>').join("")+'</fieldset><div class="form">'+vxFld("ta_vp","Validado por (nombre y cargo)","text",(t&&t.ValidadoPor)||vxUser())+vxFld("ta_vf","Fecha de validación","date",pxToday())+'</div><p class="note">Pautas de elección GPC 2021 (rec. 12 y 13): '+esc(VX_GPC_PREF.join(" · "))+'. TDF/3TC/DTG no cuenta como pauta de elección.</p>',val?"Validar":"Guardar",()=>{
  const pv=vxGv("ta_pv"),pd=vxGv("ta_pd");if(!pv)return"Documente si recibió TAR previo.";if(pv.startsWith("Experimentado")&&pd.length<6)return"Describa los esquemas previos.";
  const esq=val?t.Esquema:vxGv("ta_e"),ini=val?t.Inicio:vxGv("ta_i"),mot=val?t.Motivo:vxGv("ta_m");if(!esq||!ini)return"Elija el esquema y la fecha.";
  const apl=vxTarChkApl(p,esq,mot);const ch={};document.querySelectorAll("[data-tchk]").forEach(el=>ch[el.dataset.tchk]=el.checked);
  const falta=VX_TARCHK.filter(([k])=>(apl[k]===undefined||apl[k])&&!ch[k]).map(([k,l])=>l);if(falta.length)return"Falta validar: "+falta.join("; ")+".";
  if(apl.c5&&!(hla&&/Negativo/.test(hla.Resultado)))return"El esquema tiene abacavir y no hay HLA-B*5701 negativo registrado en Laboratorios.";
  if(!vxGv("ta_vp"))return"Escriba quién valida.";vxUpd("pac",p,{TARPrevio:pv,TARPrevioDetalle:pd});const V={Validacion:JSON.stringify(ch),ValidadoPor:vxGv("ta_vp"),FechaValidacion:vxGv("ta_vf"),TARPrevio:pv};
  if(val){vxUpd("tar",t,V);}else{if(s.tar&&vxD(ini)<=vxD(s.tar.Inicio))return"El nuevo esquema debe iniciar después del actual.";if(s.tar)vxUpd("tar",s.tar,{Fin:ini});vxAdd("tar","TA-",Object.assign({Paciente:pid,Inicio:ini,Fin:"",Esquema:esq,Linea:vxGv("ta_l"),Motivo:mot},V));}
  pxRender();toast(val?"Esquema validado.":"Esquema registrado y validado.");});}

