 const T={ppd:"Tuberculina (PPD)",ccv:"Citología cervicovaginal",can:"Citología anal"}[sub];const F=sub==="ppd"?vxPPD:(p=>vxCit(p,T));const R=P.map(p=>({p,e:F(p)})).filter(r=>r.e.cls!=="base");
 const grp={};R.forEach(r=>{const g=r.e.cls==="ok"?"Al día":r.e.cls==="info"?"Por caracterizar":/por aplicar|por tomar/.test(r.e.est)?"Ordenadas":/leer|Lectura|resultado pendiente/.test(r.e.est)?(sub==="ppd"?"Por leer":"Resultado pendiente"):/Positiva sin|Anormal|insatisfactoria/.test(r.e.est)?"Requieren conducta":"Por ordenar";(grp[g]=grp[g]||[]).push(r);});
 const ord=["Por ordenar","Ordenadas","Por leer","Resultado pendiente","Requieren conducta","Por caracterizar","Al día"];
