 T.forEach((x,i)=>{const lbl=["E","F","M","A","M","J","J","A","S","O","N","D"][x.c.getMonth()]+String(x.c.getFullYear()).slice(2);if(x.pct!=null){s+='<rect x="'+(X(i)-bw/2)+'" y="'+Y(x.pct)+'" width="'+bw+'" height="'+(Y(0)-Y(x.pct))+'" rx="2" fill="'+(col[x.cls]||"var(--accent)")+'" opacity=".85"><title>'+iso(x.c)+': '+vxF(x.pct,1)+' % ('+x.num+'/'+x.den+')</title></rect>';if(T.length<=12)s+='<text x="'+X(i)+'" y="'+(Y(x.pct)-4)+'" text-anchor="middle" class="val" style="font-size:10.5px">'+Math.round(x.pct)+'</text>';}else s+='<text x="'+X(i)+'" y="'+(Y(0)-4)+'" text-anchor="middle" class="ax">s/d</text>';s+='<text x="'+X(i)+'" y="'+(H-10)+'" text-anchor="middle" class="ax">'+lbl+'</text>';});
